package tlsxtest

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"net"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// Certs holds the paths to a CA + server cert/key + client cert/key
// generated by GenerateCerts.
type Certs struct {
	CAPath         string
	ServerCertPath string
	ServerKeyPath  string
	ClientCertPath string
	ClientKeyPath  string
}

// GenerateCerts writes a CA, a server cert (with SAN 127.0.0.1), and a
// client cert into dir. Returns paths for convenience. Intended for use only
// in tests; do not call from production code.
func GenerateCerts(t *testing.T, dir string) Certs {
	t.Helper()
	ca, caKey := mustCert(t, "test-ca", nil, nil, true)
	server, serverKey := mustCert(t, "test-server", ca, caKey, false, withIP(net.IPv4(127, 0, 0, 1)))
	client, clientKey := mustCert(t, "tmgr-test", ca, caKey, false)
	return Certs{
		CAPath:         writePEM(t, dir, "ca.crt", "CERTIFICATE", ca.Raw),
		ServerCertPath: writePEM(t, dir, "server.crt", "CERTIFICATE", server.Raw),
		ServerKeyPath:  writeECKey(t, dir, "server.key", serverKey),
		ClientCertPath: writePEM(t, dir, "client.crt", "CERTIFICATE", client.Raw),
		ClientKeyPath:  writeECKey(t, dir, "client.key", clientKey),
	}
}

type certOpt func(*x509.Certificate)

func withIP(ip net.IP) certOpt {
	return func(c *x509.Certificate) { c.IPAddresses = append(c.IPAddresses, ip) }
}

func mustCert(t *testing.T, cn string, parent *x509.Certificate, parentKey *ecdsa.PrivateKey, isCA bool, opts ...certOpt) (*x509.Certificate, *ecdsa.PrivateKey) {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	tmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(time.Now().UnixNano()),
		Subject:               pkix.Name{CommonName: cn},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(24 * time.Hour),
		KeyUsage:              x509.KeyUsageDigitalSignature | x509.KeyUsageKeyEncipherment,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
		BasicConstraintsValid: true,
		IsCA:                  isCA,
	}
	if isCA {
		tmpl.KeyUsage |= x509.KeyUsageCertSign
	}
	for _, opt := range opts {
		opt(tmpl)
	}
	if parent == nil {
		parent, parentKey = tmpl, key
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, parent, &key.PublicKey, parentKey)
	if err != nil {
		t.Fatal(err)
	}
	cert, _ := x509.ParseCertificate(der)
	return cert, key
}

func writePEM(t *testing.T, dir, name, typ string, der []byte) string {
	t.Helper()
	path := filepath.Join(dir, name)
	f, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	if err := pem.Encode(f, &pem.Block{Type: typ, Bytes: der}); err != nil {
		t.Fatal(err)
	}
	return path
}

func writeECKey(t *testing.T, dir, name string, key *ecdsa.PrivateKey) string {
	t.Helper()
	der, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		t.Fatal(err)
	}
	return writePEM(t, dir, name, "EC PRIVATE KEY", der)
}
